(function ($) {
	'use strict';

	var isAdmin = document.body && document.body.classList.contains('wp-admin');

	// Items hidden by search or by an add-on filter.
	var HIDDEN = '.tc-acc-filtered-out, .tc-acc-hidden';
	var desktopQuery = window.matchMedia ? window.matchMedia('(min-width: 768px)') : null;

	function isDesktop() {
		return desktopQuery ? desktopQuery.matches : true;
	}

	function decodeHash() {
		var h = window.location.hash.replace(/^#/, '');
		try {
			return decodeURIComponent(h);
		} catch (err) {
			return h;
		}
	}

	function normalizeText(str) {
		return (str || '').toLowerCase().replace(/\s+/g, ' ').trim();
	}

	// Swap the Font Awesome icon of a header, reading icon classes from its own accordion.
	function updateIconFor($head, isOpen) {
		var $wrap  = $head.closest('.tc-accordion-wrapper');
		var closed = $wrap.attr('data-closed-icon');
		var open   = $wrap.attr('data-open-icon');
		if (!closed || !open) return;

		var $icon = $head.find('.responsive-accordion-icon i');
		if ($icon.length) {
			if (isOpen) {
				$icon.removeClass(closed).addClass(open);
			} else {
				$icon.removeClass(open).addClass(closed);
			}
		}
	}

	// Open an item without animation (used for the parents of a deep-linked nested item).
	function forceOpen($li) {
		var $head = $li.children('.responsive-accordion-head');
		if ($head.hasClass('active')) return;

		$head.addClass('active').attr('aria-expanded', 'true');
		$li.addClass('tc-acc-open');
		$li.children('.responsive-accordion-panel').stop(true, true).show();
		updateIconFor($head, true);
	}

	function initAccordion($wrapper) {
		const autoOpenAttr    = $wrapper.attr('data-auto-open');
		const closeableAttr   = $wrapper.attr('data-closeable');
		const closeOthersAttr = $wrapper.attr('data-close-others');

		const openEvent     = $wrapper.attr('data-open-event') || 'click';
		const animSpeedAttr = $wrapper.attr('data-anim-speed');
		const animSpeed     = animSpeedAttr ? parseInt(animSpeedAttr, 10) : 200;
		const layout        = $wrapper.attr('data-layout') || 'accordion';

		const autoOpenIndex = autoOpenAttr ? parseInt(autoOpenAttr, 10) - 1 : -1;
		const isCloseable   = closeableAttr !== 'no';
		const closeOthers   = closeOthersAttr !== 'no';

		// Deep links are disabled inside the WordPress admin preview.
		const deepLink = $wrapper.attr('data-deep-link') === 'yes' && !isAdmin;

		// Only this accordion's own items (nested accordions are excluded).
		const $items = $wrapper.children('.responsive-accordion').children('li');

		// True when a handler event belongs to this accordion and not a nested one.
		function isOwn(el) {
			return $(el).closest('.tc-accordion-wrapper')[0] === $wrapper[0];
		}

		// Optional layout behavior (for example Tabs or Horizontal) supplied by an add-on script
		// through window.TCAccordionLayouts. Without one, the accordion behaves normally.
		let layoutMode = null;

		function modeActive() {
			return !!(layoutMode && layoutMode.active());
		}
		function closeOthersNow() {
			return closeOthers || (modeActive() && !!layoutMode.forceCloseOthers);
		}
		function closeableNow() {
			return isCloseable && !(modeActive() && layoutMode.alwaysOneOpen);
		}

		function setExpanded($head, isOpen) {
			$head.attr('aria-expanded', isOpen ? 'true' : 'false');
		}

		// Central state change for one item.
		function setOpen($li, open, instant, silent) {
			const $head  = $li.children('.responsive-accordion-head');
			const $panel = $li.children('.responsive-accordion-panel');

			$head.toggleClass('active', open);
			$li.toggleClass('tc-acc-open', open);
			updateIconFor($head, open);
			setExpanded($head, open);

			$panel.stop(true, true);

			// Tell add-ons (for example analytics) that a visitor opened an item.
			if (open && !instant && !silent) {
				$li.trigger('tcacc_item_open');
			}

			if (instant) {
				$panel.toggle(open);
			} else if (modeActive() && layoutMode.togglePanel) {
				layoutMode.togglePanel($panel, open, $head);
			} else if (open) {
				$panel.slideDown(animSpeed);
			} else {
				$panel.slideUp(animSpeed);
			}
		}

		// ---- Deep link helpers -------------------------------------------
		function setHash(anchor) {
			if (!deepLink || !anchor || !window.history || !window.history.replaceState) return;
			window.history.replaceState(null, '', window.location.pathname + window.location.search + '#' + encodeURIComponent(anchor));
		}

		function clearHash(anchor) {
			if (!deepLink || !window.history || !window.history.replaceState) return;
			if (decodeHash() === anchor) {
				window.history.replaceState(null, '', window.location.pathname + window.location.search);
			}
		}

		// Finds the matching item in this accordion or in a nested accordion inside it.
		function findItemByHash() {
			const hash = decodeHash();
			if (!hash) return $();
			return $wrapper.find('li[data-anchor]').filter(function () {
				return $(this).attr('data-anchor') === hash;
			}).first();
		}

		// Ask the layout add-on (if any) to describe how this layout behaves.
		const layoutFactory = window.TCAccordionLayouts && window.TCAccordionLayouts[layout];
		if (typeof layoutFactory === 'function') {
			layoutMode = layoutFactory({
				$wrapper: $wrapper,
				$items: $items,
				animSpeed: animSpeed,
				isDesktop: isDesktop,
				setOpen: setOpen
			});
		}

		// Initial state
		const startIndex = autoOpenIndex >= 0 ? autoOpenIndex : ((modeActive() && layoutMode.alwaysOneOpen) ? 0 : -1);
		$items.each(function (index) {
			setOpen($(this), index === startIndex, true);
		});

		// Core Toggle Action
		function toggleItem($head, opts) {
			opts = opts || {};

			const $li      = $head.parent('li');
			const isActive = $head.hasClass('active');

			if (isActive && !closeableNow()) {
				return;
			}

			if (closeOthersNow()) {
				$items.not($li).each(function () {
					if ($(this).children('.responsive-accordion-head').hasClass('active')) {
						setOpen($(this), false, opts.instant);
					}
				});
			}

			if (isActive) {
				setOpen($li, false, opts.instant);
				clearHash($li.attr('data-anchor'));
			} else {
				setOpen($li, true, opts.instant);
				setHash($li.attr('data-anchor'));
			}
		}

		// Open the item matching the URL hash (deep link), including its parent items.
		function openFromHash(doScroll) {
			if (!deepLink) return;

			const $li = findItemByHash();
			if (!$li.length) return;

			// Parents first (outermost to innermost), then the item itself.
			const chain = $li.parents('li').get().reverse();
			chain.push($li[0]);

			$.each(chain, function (_, el) {
				const $el = $(el);
				if (!$el.parent().hasClass('responsive-accordion')) return;

				if ($items.is(el)) {
					const $h = $el.children('.responsive-accordion-head');
					if (!$h.hasClass('active')) {
						toggleItem($h, { instant: true });
					}
				} else {
					forceOpen($el);
				}
			});

			if (doScroll) {
				// A layout can make the item box "display: contents", so scroll to its header instead.
				const target = ($li.css('display') === 'contents') ? $li.children('.responsive-accordion-head')[0] : $li[0];
				if (target && target.scrollIntoView) {
					const reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
					setTimeout(function () {
						target.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
					}, 60);
				}
			}
		}

		// Keep open/closed state valid when the screen crosses the 768px breakpoint.
		function syncMode() {
			if (modeActive() && layoutMode.sync) {
				layoutMode.sync();
			}

			// Make sure panel visibility matches each item's state.
			$items.each(function () {
				const $li = $(this);
				const open = $li.children('.responsive-accordion-head').hasClass('active');
				$li.children('.responsive-accordion-panel').stop(true, true).css('display', open ? 'block' : 'none');
			});
		}

		// ---- Expand all / Collapse all ------------------------------------
		$wrapper.off('.tctools');

		const $toolbar = $wrapper.children('.tc-accordion-tools');

		function updateToolbar() {
			// A layout that always keeps one panel open (Tabs) cannot expand or collapse everything.
			const onlyOne = modeActive() && !!layoutMode.alwaysOneOpen;
			$toolbar.find('.tc-accordion-expand-all').toggle(!onlyOne);
			$toolbar.find('.tc-accordion-collapse-all').toggle(isCloseable && !onlyOne);
		}
		updateToolbar();

		$wrapper.on('click.tctools', '.tc-accordion-expand-all', function (e) {
			if (!isOwn(this)) return;
			e.preventDefault();
			$items.not(HIDDEN).each(function () {
				if (!$(this).children('.responsive-accordion-head').hasClass('active')) {
					setOpen($(this), true, false, true);
				}
			});
		});

		$wrapper.on('click.tctools', '.tc-accordion-collapse-all', function (e) {
			if (!isOwn(this)) return;
			e.preventDefault();
			$items.each(function () {
				if ($(this).children('.responsive-accordion-head').hasClass('active')) {
					setOpen($(this), false);
					clearHash($(this).attr('data-anchor'));
				}
			});
		});

		// ---- Live search ---------------------------------------------------
		const $noResults = $wrapper.children('.tc-accordion-no-results');
		let searchTimer;

		function filterItems(query) {
			const words = normalizeText(query).split(' ').filter(Boolean);
			let found = 0;

			$items.each(function () {
				const $li = $(this);
				let text = $li.data('tcText');
				if (typeof text === 'undefined') {
					text = normalizeText($li.text());
					$li.data('tcText', text);
				}

				const match = words.every(function (word) {
					return text.indexOf(word) !== -1;
				});

				$li.toggleClass('tc-acc-filtered-out', !match);
				if (match) {
					found++;
				}
			});

			$noResults.prop('hidden', !(words.length && found === 0));

			if (modeActive() && layoutMode.afterFilter) {
				layoutMode.afterFilter();
			}
		}

		$wrapper.on('input.tctools search.tctools', '.tc-accordion-search', function () {
			if (!isOwn(this)) return;
			const value = this.value;
			clearTimeout(searchTimer);
			searchTimer = setTimeout(function () {
				filterItems(value);
			}, 120);
		});

		// An add-on changed which items are visible (for example group filter tabs).
		$wrapper.on('tcacc_items_changed.tctools', function (e) {
			if (e.target !== $wrapper[0]) return;
			if (modeActive() && layoutMode.afterFilter) {
				layoutMode.afterFilter();
			}
		});

		// ---- Keyboard navigation between headers (supplied by the layout, if it has any) ----
		$wrapper.on('keydown.tctools', '.responsive-accordion-head', function (e) {
			if (!isOwn(this) || !modeActive() || !layoutMode.nextIndex) return;

			const $heads  = $items.not(HIDDEN).children('.responsive-accordion-head');
			const current = $heads.index(this);
			if (current === -1) return;

			const next = layoutMode.nextIndex(e.key, current, $heads.length);
			if (typeof next !== 'number' || next < 0) return;

			e.preventDefault();
			$heads.eq(next).trigger('focus');
		});

		// Re-sync when the screen crosses the desktop breakpoint.
		if (desktopQuery) {
			const onChange = function () {
				syncMode();
				updateToolbar();
			};
			// Remove any listener from a previous init of this wrapper.
			const previous = $wrapper.data('tcaccMqListener');
			if (previous) {
				if (desktopQuery.removeEventListener) {
					desktopQuery.removeEventListener('change', previous);
				} else if (desktopQuery.removeListener) {
					desktopQuery.removeListener(previous);
				}
			}
			if (desktopQuery.addEventListener) {
				desktopQuery.addEventListener('change', onChange);
			} else if (desktopQuery.addListener) {
				desktopQuery.addListener(onChange);
			}
			$wrapper.data('tcaccMqListener', onChange);
		}

		// Expose a small API so the hashchange listener can reach this accordion.
		$wrapper.data('tcaccApi', { openFromHash: openFromHash });

		// Unbind previous event handlers to prevent duplicate execution during re-init
		$wrapper.off('click mouseenter', '.responsive-accordion-head');

		// Bind Click or Hover Event
		if (openEvent === 'hover') {
			$wrapper.on('mouseenter', '.responsive-accordion-head', function () {
				if (!isOwn(this)) return;
				toggleItem($(this));
			});
		} else {
			$wrapper.on('click', '.responsive-accordion-head', function (e) {
				if (!isOwn(this)) return;
				e.preventDefault();
				toggleItem($(this));
			});
		}

		// Open a deep-linked item on page load
		openFromHash(true);
	}

	// Initialize on page load
	$(document).ready(function () {
		$('.tc-accordion-wrapper').each(function () {
			initAccordion($(this));
		});
	});

	// Open the matching item when the URL hash changes (e.g. clicking an in-page link)
	$(window).on('hashchange.tcacc', function () {
		$('.tc-accordion-wrapper').each(function () {
			const api = $(this).data('tcaccApi');
			if (api) {
				api.openFromHash(true);
			}
		});
	});

	// Support re-initialization (e.g., WordPress Live Preview / Gutenberg / AJAX)
	$(document).on('tc_accordion_reinit', function (e, targetWrapper) {
		if (targetWrapper) {
			initAccordion($(targetWrapper));
		} else {
			$('.tc-accordion-wrapper').each(function () {
				initAccordion($(this));
			});
		}
	});

	document.addEventListener('DOMContentLoaded', function () {
	    // 1. Keyboard Navigation (Enter and Space key trigger)
	    document.addEventListener('keydown', function (e) {
	        if ((e.key === ' ' || e.key === 'Enter') && e.target.classList.contains('responsive-accordion-head')) {
	            e.preventDefault(); // Stop page scrolling on Spacebar
	            e.target.click();   // Trigger click event
	        }
	    });

	    // 2. Dynamic ARIA Expanded Sync
	    document.querySelectorAll('.responsive-accordion-head').forEach(function (head) {
	        head.addEventListener('click', function () {
	            var wrapper = head.closest('.tc-accordion-wrapper');
	            var isCloseOthers = wrapper && wrapper.getAttribute('data-close-others') === 'yes';

	            if (isCloseOthers) {
	                wrapper.querySelectorAll(':scope > .responsive-accordion > li > .responsive-accordion-head').forEach(function (otherHead) {
	                    otherHead.setAttribute('aria-expanded', 'false');
	                });
	            }

	            setTimeout(function () {
	                var isActive = head.classList.contains('active');
	                head.setAttribute('aria-expanded', isActive ? 'true' : 'false');
	            }, 50);
	        });
	    });
	});

})(jQuery);
